const CACHE='insidestory-mixpalette-v11';const ASSETS=['./','./index.html','./styles.css?v=11','./app.js?v=11','./vallejo-colors.json?v=8','./manifest.webmanifest','./icon-v2.svg'];self.addEventListener('install',e=>{self.skipWaiting();e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)))});self.addEventListener('activate',e=>e.waitUntil(Promise.all([self.clients.claim(),caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE).map(k=>caches.delete(k))))])));self.addEventListener('fetch',e=>{if(e.request.mode==='navigate'){e.respondWith(fetch(e.request).then(x=>{const c=x.clone();caches.open(CACHE).then(v=>v.put('./index.html',c));return x}).catch(()=>caches.match('./index.html')));return}e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request).then(x=>{const c=x.clone();caches.open(CACHE).then(v=>v.put(e.request,c));return x}))) });
